A \textbf{symmetric monoidal poset}
(\textbf{SM-P})
$\mathcal{V}$ is a triple
$(\mathcal{V}_0,\otimes,e)$
where
\begin{itemize}
	\item
	$\mathcal{V}_0=(\mathcal{V}_0,\sqsubseteq)$ 
	is a poset called the \textbf{underlying poset};
	\item
	$\otimes\colon\mathcal{V}_0\times\mathcal{V}_0\longrightarrow \mathcal{V}_0$ is a binary operation on
	$\mathcal{V}_0$
	called the \textbf{tensor product};
	\item
	$e$ is an element of $\mathcal{V}_0$ called the 
	\textbf{unit element};
\end{itemize}
such that the following axioms hold:
\begin{description}[font=\normalfont]
	\item[$\qquad$(Monotonicity of $\otimes$)]
	$x\sqsubseteq x^\prime$ and $y\sqsubseteq y^\prime$ imply $x\otimes y\sqsubseteq x^\prime\otimes y^\prime\quad (\forall x,x^\prime,y,y^\prime\in \mathcal{V}_0)$;
	\item[$\qquad$(Associative law)]
	$x\otimes (y\otimes z)=(x\otimes y)\otimes z\quad(\forall x,y,z\in \mathcal{V}_0)$;
	\item[$\qquad$(Unit law for $\otimes$)]
	$e\otimes x=x=x\otimes e\quad(\forall x\in \mathcal{V}_0)$;
	\item[$\qquad$(Commutative law for $\otimes$)]
	$x\otimes y=y\otimes x\quad (\forall x,y\in \mathcal{V}_0)$.
\end{description}
A \textbf{symmetric monoidal complete lattice} 
(\textbf{SM-CL}) is
an SM-P whose underlying poset $\mathcal{V}_0$
is a complete lattice.

A \textbf{symmetric closed poset}
(\textbf{SC-P})
$\mathcal{V}$ is a triple
$(\mathcal{V}_0,[-,-],e)$
where
\begin{itemize}
	\item
	$\mathcal{V}_0=(\mathcal{V}_0,\sqsubseteq)$ 
	is a poset called the \textbf{underlying poset};
	\item
	$[-,-]\colon\mathcal{V}_0^\textup{op}\times\mathcal{V}_0\longrightarrow \mathcal{V}_0$ is a binary operation on
	$\mathcal{V}_0$
	called the \textbf{internal-hom};
	\item
	$e$ is an element of $\mathcal{V}_0$ called the 
	\textbf{unit element};
\end{itemize}
such that the following axioms hold:
\begin{description}[font=\normalfont]
	\item[$\qquad$(Monotonicity of \mbox{$[-,-]$})]
	$y\sqsupseteq y^\prime$ and $z\sqsubseteq z^\prime$ imply $[y,z]\sqsubseteq [y^\prime, z^\prime]\quad (\forall y,y^\prime,z,z^\prime\in \mathcal{V}_0)$;
	\item[$\qquad$(Composition law)]
	$[y,z]\sqsubseteq [[x,y],[x,z]]\quad(\forall x,y,z\in\mathcal{V}_0)$;
	\item[$\qquad$(Unit law for \mbox{$[-,-]$})]
	$z=[e,z]\quad(\forall z\in \mathcal{V}_0)$;
	\item[$\qquad$(Commutative law for \mbox{$[-,-]$})]
	$x\sqsubseteq [y,z]\iff y\sqsubseteq[x,z]\quad(\forall x,y,z\in \mathcal{V}_0)$.
\end{description}
A \textbf{symmetric closed complete lattice} 
(\textbf{SC-CL}) is
an SC-P whose underlying poset $\mathcal{V}_0$
is a complete lattice.

A \textbf{symmetric monoidal closed poset}
(\textbf{SMC-P})
$\mathcal{V}$ is a quadruple
$(\mathcal{V}_0,\otimes,$ $[-,-],e)$
where
\begin{itemize}
	\item
	the triple $(\mathcal{V}_0,\otimes,e)$ is an SM-P;
	\item
	the triple $(\mathcal{V}_0,[-,-],e)$ is an SC-P;
\end{itemize}
such that these two structures are related as follows:
\begin{description}[font=\normalfont]
	\item[$\qquad$(Adjointness relation)]
	$x\otimes y\sqsubseteq z\iff x\sqsubseteq [y,z]\quad(\forall x,y,z\in \mathcal{V}_0)$.
\end{description}
A \textbf{symmetric monoidal closed complete lattice}
(\textbf{SMC-CL}) is
an SMC-P whose underlying poset $\mathcal{V}_0$
is a complete lattice.

\label{ex:Rplus}                
The quadruple
$\overline{\mathbb{R}}_+=(\mathbb{R}_+\cup\{\infty\},+,\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}},0)$
is defined as follows:
\begin{itemize}
\item
$\mathbb{R}_+\cup\{\infty\}=(\mathbb{R}_+\cup\{\infty\},\geq)$
is the set of nonnegative real numbers 
$\mathbb{R}_+=\{x\in\mathbb{R}\mid$ $x\geq 0\}$
with an additional element $\infty$, 
ordered by the \textit{opposite} $\geq$ of 
the usual ordering $\leq$ (extended from $\mathbb{R}_+$
to $\mathbb{R}_+\cup\{\infty\}$ in an obvious way).
More explicitly, supposing $s,t\in \mathbb{R}_+$ (thus we
already know whether $s\geq t$ holds or not), the order is
given by the following table: 
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$x\geq y$}} &\multicolumn{2}{c}{$y$} \\	    
    &  & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$x$} &$s$ & $s\geq t$ & $\times$ \\
    &$\infty$ & $\fullmoon$ & $\fullmoon$ 
	\end{tabular}
\end{table}
\item
$+$ is the binary operation defined as the
natural extension of the usual addition:
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$x+y$}}& \multicolumn{2}{c}{$y$} \\	    
    &   & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$x$} &$s$ & $s+t$ & $\infty$ \\
    &$\infty$  & $\infty$ & $\infty$ 
	\end{tabular}
\end{table}
\item
$\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ is the binary operation called the truncated
subtraction. To define this, we first set
$t\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s=\max\{t-s,0\}$ for $s,t\in \mathbb{R}_+$.
Then the domain of $\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ is extended to 
$\mathbb{R}_+\cup\{\infty\}$ as follows
(note the order of the arguments; we set $[x,y]=y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} x$):
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} x$}}& \multicolumn{2}{c}{$y$} \\	    
	&   & $t$ & $\infty$\\ \hline
	\multirow{2}{*}{$x$} &$s$ & $t\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s$ & $\infty$ \\
	&$\infty$  & $0$ & $0$
	\end{tabular}
\end{table}
\end{itemize}
Then it turns out that $\overline{\mathbb{R}}_+$ is an
SMC-CL.

The reader may feel that the definition of  
the extended operations is somewhat arbitrary, 
especially in the case $\infty\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}\infty=0$.
We first note that, contrary to such a view,
\textit{in order
$\overline{\mathbb{R}}_+$ 
to be an SMC-CL,
the extensions of $+$ and $\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ are 
completely determined as soon as we extend the order}
$\geq$.
To see this, recall from Propositions 
\ref{prop:SMCCL} and \ref{prop:lim_ten_hom} that
necessary conditions for the quadruple 
$\overline{\mathbb{R}}_+=(\mathbb{R}_+\cup\{\infty\},+,\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}},0)$
to be an SMC-CL are that 
{\allowdisplaybreaks
\begin{align}
	\label{lim_ten1} & x+(-) \text{ preserves suprema for each } 
	x\in \mathbb{R}_+\cup\{\infty\};\\
	\label{lim_ten2} & (-)+y \text{ preserves suprema for each }
	y\in \mathbb{R}_+\cup\{\infty\};\\
	\label{lim_hom1} & (-)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} x \text{ preserves infima for each }
	x\in \mathbb{R}_+\cup\{\infty\};\\
	\label{lim_hom2} & y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} (-) \text{ turns suprema into infima for each }
	y\in \mathbb{R}_+\cup\{\infty\}.
\end{align}}
\!\!Now that
we are working with the opposite ordering $\geq$,
which means our supremum $\bigvee$ corresponds to the 
usual infimum (for which we use a different 
symbol $\inf$) and dually, we obtain the
following for each 
$x,y\in \mathbb{R}_+\cup \{\infty\}$ and
$s\in \mathbb{R}_+$:
{\allowdisplaybreaks
\begin{align*}
	& x+\infty = x+\inf \emptyset 
	\overset{\text{(\ref{lim_ten1})}}=
	\inf \emptyset = \infty; \\
	&\infty+y = \inf \emptyset+y 
	\overset{\text{(\ref{lim_ten2})}}=
	\inf \emptyset = \infty; \\
	&\infty\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s = \sup_{t\in \mathbb{R}_+}\{t\} \mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s 
	\overset{\text{(\ref{lim_hom1})}}=
	\sup_{t\in \mathbb{R}_+}\{t\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s\} = \infty;\\
	& y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} \infty = y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} \inf\emptyset
	\overset{\text{(\ref{lim_hom2})}}= 
	\sup \emptyset = 0. 
\end{align*}}
\!\!These specify the extensions.

We then show that $\overline{\mathbb{R}}_+$ is indeed
an SMC-CL,
following the condition (ii) of 
Proposition~\ref{prop:SMCCL}.
\begin{description}[font=\normalfont]
\item[[$\mathbb{R}_+\cup\{\infty\}$ is a complete lattice\!\!\!]]
A well-known fact.
\item[[Monotonicity of $+$\!\!\!]]
Suppose $x\geq x^\prime$ and $y\geq y^\prime$ hold.
If all of $x,x^\prime,y,y^\prime$ are elements of
$\mathbb{R}_+$, then 
$x+y\geq x^\prime +y^\prime$ holds.
Otherwise, either $x$ or $y$ is $\infty$; 
thus $x+y=\infty$ and again
$x+y\geq x^\prime +y^\prime$ holds.
\item[[Associative law\!\!\!]]
The claim is $x+(y+z)=(x+y)+z$. 
If all of $x,y,z$ are elements of
$\mathbb{R}_+$, the claim reduces to an
elementary fact.
Otherwise, one of $x,y,z$ is $\infty$,
and both of $x+(y+z)$ and $(x+y)+z$
are equal to $\infty$.
\item[[Unit law\!\!\!]]
The claim is $0+x=x=x+0$. 
If $x\in \mathbb{R}_+$, it certainly holds; 
if not, $0+\infty=\infty=\infty+0$ and again it holds. 
\item[[Commutative law\!\!\!]]
The claim is $x+y=y+x$. 
If $x,y\in \mathbb{R}_+$, it holds. 
Otherwise, both sides are
equal to $\infty$.
\item[[$(-)+y$ preserves suprema\!\!\!]]
If $y=\infty$, the function $(-)+y$ constantly returns
$\infty$, which is also the least element
(the supremum of the empty set).
Thus it preserves all suprema.

Suppose $y\in \mathbb{R}_+$ and take an 
arbitrary family $x_i\in \mathbb{R}_+\cup \{\infty\}$ 
$(i\in I)$.
We aim to prove 
\begin{align}\label{sup_preserve}
	\inf_{i\in I}\{x_i\}+y=\inf_{i\in I}\{x_i+y\}.
\end{align}

If $\inf_{i\in I}\{x_i\}=\infty$, then
for all $i\in I$, $x_i=\infty$.
Therefore for all $i\in I$, $x_i+y=\infty$
and both sides of (\ref{sup_preserve}) evaluate
to $\infty$.

If $\inf_{i\in I}\{x_i\}\in \mathbb{R}_+$, then 
there exists $i\in I$ with $x_i\in \mathbb{R}_+$, 
and we may simply omit those $x_i$'s with 
$x_i=\infty$, obtaining a new family 
$x_i\in \mathbb{R}_+$ $(i\in I\neq \emptyset)$
of nonnegative real numbers.
Now (\ref{sup_preserve}) essentially reduces to
the continuity of $+$.
\end{description}

Finally, we show that $\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ is indeed the 
internal-hom, by checking 
the adjointness relation.
\begin{description}[font=\normalfont]
\item[[$x+y\geq z\implies x\geq z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y\!\!\!$]]
The monotonicity of $\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ is easily verified.
Therefore, $x+y\geq z$ implies 
$(x+y)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y\geq z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y$.
So it suffices to show $x\geq (x+y)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y$, 
which follows from the table below:
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$(x+y)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y$}} &\multicolumn{2}{c}{$y$} \\	    
    &  & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$\;\,\quad x$} &$s$ & $s$ & $0$ \\
    &$\infty$ & $\infty$ & $0$ 
	\end{tabular}
\end{table}
\item[[$x\geq z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y\implies x+y\geq z\!\!\!$]]
By the monotonicity of $+$, $x\geq z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y$ implies
$x+y\geq (z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y)+y$.
So it suffices to show $(z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y)+y\geq z$,
which follows from the table below:
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$(z\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} y)+y$}} &\multicolumn{2}{c}{$z$} \\	    
    &  & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$\;\,\quad y$} &$s$ & $\max\{s,t\}$ & $\infty$ \\
    &$\infty$ & $\infty$ & $\infty$ 
	\end{tabular}
\end{table}
\end{description}

The quadruple
$\overline{\mathbb{Z}}_+=(\mathbb{Z}_+\cup\{\infty\},+,\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}},0)$
is defined as follows:
\begin{itemize}
\item
$\mathbb{Z}_+\cup\{\infty\}=(\mathbb{Z}_+\cup\{\infty\},\geq)$
is the set of nonnegative integers 
$\mathbb{Z}_+=\{x\in\mathbb{Z}\mid$ $x\geq 0\}$
with an additional element $\infty$, 
ordered by $\geq$, the order relation
similar to that on 
$\mathbb{R}_+\cup\{\infty\}$. 
For $s,t\in \mathbb{Z}_+$, it is given as follows: 
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$x\geq y$}} &\multicolumn{2}{c}{$y$} \\	    
    &  & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$x$} &$s$ & $s\geq t$ & $\times$ \\
    &$\infty$ & $\fullmoon$ & $\fullmoon$ 
	\end{tabular}
\end{table}
\item
$+$ is an extension of the usual addition:
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$x+y$}}& \multicolumn{2}{c}{$y$} \\	    
    &   & $t$ & $\infty$\\ \hline
    \multirow{2}{*}{$x$} &$s$ & $s+t$ & $\infty$ \\
    &$\infty$  & $\infty$ & $\infty$ 
	\end{tabular}
\end{table}
\item
$\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$ is an extension of
the operation defined as
$t\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s=\max\{t-s,0\}$:
\begin{table}[H]
	\centering
	\begin{tabular}{c c|c c}
	\multicolumn{2}{c|}{\multirow{2}{*}{$y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} x$}}& \multicolumn{2}{c}{$y$} \\	    
	&   & $t$ & $\infty$\\ \hline
	\multirow{2}{*}{$x$} &$s$ & $t\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} s$ & $\infty$ \\
	&$\infty$  & $0$ & $0$
	\end{tabular}
\end{table}
\end{itemize}
$\overline{\mathbb{Z}}_+$ is an SMC-CL;
its proof is obtained by a slight modification
to that for $\overline{\mathbb{R}}_+$.
Again we have no choice for extensions of operations $+$ and 
$\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}}$.

Let $\mathcal{V}=(\mathcal{V}_0,\otimes,e)$ be
an SM-P. 
A $\mathcal{V}$\textbf{-category}
$\mathcal{A}$ is a pair
$(\textup{Ob}(\mathcal{A}),$ $\textup{Hom}_\mathcal{A})$ where
\begin{itemize}
	\item $\textup{Ob}(\mathcal{A})$ is the set of
	\textbf{objects} of $\mathcal{A}$;
	\item $\textup{Hom}_\mathcal{A}$ is a map which
	assigns for each pair $a,b$ of objects 
	of $\mathcal{A}$,
	an element $\textup{Hom}_\mathcal{A}(a,b)$ of
	$\mathcal{V}_0$ called its
	\textbf{hom-object};
\end{itemize}
such that the following axioms hold:
\begin{description}[font=\normalfont]
	\item[$\qquad$(Composition law)]
	$\textup{Hom}_\mathcal{A}(a,b)\otimes\textup{Hom}_\mathcal{A}(b,c)\sqsubseteq\textup{Hom}_\mathcal{A}(a,c)\quad(\forall a,b,c\in \textup{Ob}(\mathcal{A}))$;
	\item[$\qquad$(Identity law)]
	$e\sqsubseteq\textup{Hom}_\mathcal{A}(a,a)\quad(\forall a\in \textup{Ob}(\mathcal{A}))$.
\end{description}

\begin{align*}
e&= e\otimes e\\
&\sqsubseteq \textup{Hom}_{\mathcal{B}}\big(F(a),F(a)\big)\otimes \textup{Hom}_{\mathcal{B}}\big(F(a),G(a)\big)\\
&\sqsubseteq \textup{Hom}_{\mathcal{C}}\big(H\circ F(a),K\circ F(a)\big)\otimes \textup{Hom}_{\mathcal{C}}\big(K\circ F(a),K\circ G(a)\big)\\
&\sqsubseteq \textup{Hom}_{\mathcal{C}}\big(H\circ F(a),K\circ G(a)\big).
\end{align*}

The set
$\mathbb{K}_+\cup\{\infty\}$
becomes a $\overline{\mathbb{K}}_+$-category 
by the following distance function:
\[
	d_{\overline{\mathbb{K}}_+}(x,y)=y\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} x.
\]
Therefore, if $x\leq y$ the distance to climb
from $x$ to $y$ is the same as their the difference, 
but if $x\geq y$, we descend and the corresponding 
distance is $0$.

Note that the $\overline{\mathbb{K}}_+$-category 
$\overline{\mathbb{K}}_+$ is \textit{not} 
an ordinary (discrete) metric space;
among others, its distance function is highly asymmetric.

The set
$\mathbb{K}_+\cup\{\infty\}$
becomes a $\overline{\mathbb{K}}_+^\text{Cart}$-category
by the following distance function:
\begin{align*}
	d_{\overline{\mathbb{K}}_+^\text{Cart}}(x,y)
	&=x\supset y\\
	&=\begin{cases}
	0 &(x\geq y)\\
	y &(x<y).
	\end{cases}
\end{align*}

Let $\mathcal{A}=(\textup{Ob}(\mathcal{A}),d_\mathcal{A})$ 
and $\mathcal{B}=(\textup{Ob}(\mathcal{B}),d_\mathcal{B})$
be $\overline{\mathbb{K}}_+$-categories.
The functor category 
${\textup{Fun}(\mathcal{A},\mathcal{B})}=([\mathcal{A},\mathcal{B}]_0,d_{\textup{Fun}(\mathcal{A},\mathcal{B})})$ 
is given as follows, noting that $\bigwedge$ in
$\mathbb{K}_+\cup\{\infty\}$ corresponds to (the usual)
$\sup$:
\begin{itemize}
	\item $[\mathcal{A},\mathcal{B}]_0$ is the set of
	all nonexpansive maps from $\mathcal{A}$ to
	$\mathcal{B}$;
	\item $d_{\textup{Fun}(\mathcal{A},\mathcal{B})}(F,G)=
	\sup_{a\in \textup{Ob}(\mathcal{A})}
	\left\{d_\mathcal{B}\big(F(a),G(a)\big)\right\}$.
\end{itemize}
Therefore, in the current setting, the natural distance
on a function space turns out to be the sup-distance.
Since we adjoined $\infty$ and turned $\mathbb{K}_+$ into
a complete lattice, we can get rid of additional 
assumptions such as the compactness of $\mathcal{A}$ or 
the boundedness of $\mathcal{B}$, the usual 
requirements when performing the sup-distance construction
in the theory of classical metric spaces.

A presheaf $P$ on $\mathcal{A}$ is a nonexpansive map
$P\colon\mathcal{A}^\textup{op} \longrightarrow \overline{\mathbb{K}}_+$,
namely, a map 
$\textup{Ob}(P)\colon$ $\textup{Ob}(A)\longrightarrow \mathbb{K}_+\cup\{\infty\}$
satisfying 
\[
	d_\mathcal{A}(a,b)\geq P(a)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} P(b)
\]
for all $a,b\in \textup{Ob}(\mathcal{A})$,
and can be seen as a scalar-valued function on
$\mathcal{A}$.
The distance between two presheaves $P_1$ and $P_2$ is 
given by
\[
	d_{\textup{Fun}(\mathcal{A}^\textup{op},\overline{\mathbb{K}}_+)}(P_1,P_2)
	=\sup_{a\in \textup{Ob}(\mathcal{A})}
	\{P_2(a)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} P_1(a)\}.
\]
The canonical ordering $\Rightarrow$ is defined as 
\begin{align*}
	P_1\Rightarrow P_2 
	&\iff 0\geq P_2(a)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} P_1(a)\quad (\forall a\in \textup{Ob}(\mathcal{A}))\\
	&\iff P_2(a)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} P_1(a)=0\quad (\forall a\in \textup{Ob}(\mathcal{A}))\\
	&\iff d_{\textup{Fun}(\mathcal{A}^\textup{op},\overline{\mathbb{K}}_+)}(P_1,P_2)=0\\
	&\iff P_1(a)\geq P_2(a)\quad (\forall a\in \textup{Ob}(\mathcal{A})).
\end{align*}

A copresheaf $Q$ on $\mathcal{A}$ is a nonexpansive map
$Q\colon\mathcal{A} \longrightarrow \overline{\mathbb{K}}_+$,
namely, a map 
$\textup{Ob}(Q)\colon$ $\textup{Ob}(A)\longrightarrow \mathbb{K}_+\cup\{\infty\}$
satisfying 
\[
	d_\mathcal{A}(a,b)\geq Q(b)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} Q(a)
\]
for all $a,b\in \textup{Ob}(\mathcal{A})$,
and forms another natural class of scalar-valued
functions on $\mathcal{A}$.
The distance between two copresheaves $Q_1$ and $Q_2$ 
in the op-copresheaf category
${\textup{Fun}(\mathcal{A},\overline{\mathbb{K}}_+)}^\textup{op}$ 
is given by
\[
	d_{{\textup{Fun}(\mathcal{A},\overline{\mathbb{K}}_+)}^\textup{op}}(Q_1,Q_2)
	=\sup_{a\in \textup{Ob}(\mathcal{A})}
	\{Q_1(a)\mathbin{\text{ 
  \ooalign{\hidewidth\raise1ex\hbox{.}\hidewidth\cr$\m@th-$\cr} 
}} Q_2(a)\}.
\]
As $\overline{\mathbb{K}}_+$-functors, the canonical 
ordering $\Rightarrow$ on copresheaves is determined 
by conditions similar to that for presheaves.

A $\overline{\mathbb{K}}$\textbf{-extended L-convex set}
$\mathbf{D}$ is a pair 
$({\textup{Ind}(\mathbf{D})},\mathbf{D}_0)$ where
\begin{itemize}
\item 
${\textup{Ind}(\mathbf{D})}$ is a set called the \textbf{index set} 
of $\mathbf{D}$;
\item
$\mathbf{D}_0$ is a subset of 
$\overline{\mathbb{K}}^{\textup{Ind}(\mathbf{D})}$
called the \textbf{underlying set} of $\mathbf{D}$;
\end{itemize}
such that the following axioms hold:
\begin{description}[font=\normalfont]
	\item[$\qquad$(Order completeness)]
	$\bigvee_{p \in S} p,\ 
	\bigwedge_{p \in S} p\in \mathbf{D}_0
	\quad(\forall S\subseteq \mathbf{D}_0)$;
	\item[$\qquad$(Weight completeness)]
	$p+\alpha \cdot\textbf{1}\in \mathbf{D}_0\quad 
	(\forall p\in \mathbf{D}_0,\ \forall \alpha \in \mathbb{K}\cup\{-\infty,\infty\})$.
\end{description}

First note that elements of 
${\llbracket \mathbf{D},\overline{\mathbb{K}} \rrbracket}_0$ 
can canonically be identified with that of 
${\textup{Ind}(\mathbf{D})}$, 
via a bijection $\pi_\mathbf{D}$ defined as follows:
\[
	\pi_\mathbf{D}\colon {\textup{Ind}(\mathbf{D})}\longrightarrow {\llbracket \mathbf{D},\overline{\mathbb{K}} \rrbracket}_0,
	\qquad 
	\pi_\mathbf{D}(v)=\pi_v
	\quad (\forall v\in {\textup{Ind}(\mathbf{D})}),
\]
where
\[
	{\textup{Ind}(\pi_v)}\colon \{\ast\}\longrightarrow {\textup{Ind}(\mathbf{D})},\qquad
	{\textup{Ind}(\pi_v)}(\ast)=v.
\]
The underlying maps of $\pi_v$'s are given as the 
``projection maps'':
\[
(\pi_v)_0\colon \mathbf{D}_0\longrightarrow \mathbb{K}\cup\{-\infty,\infty\}\subseteq \overline{\mathbb{K}}^{\{\ast\}}\qquad
(\pi_v)_0(p)=p(v).
\]
See Fig.~\ref{fig:lcsproj} for an illustration.
Thus we may write ${\llbracket \mathbf{D},\overline{\mathbb{K}} \rrbracket}_0=\{\pi_v\}_{v\in {\textup{Ind}(\mathbf{D})}}$.
Also note that 
\begin{align}
d_{{\llbracket \mathbf{D},\overline{\mathbb{K}} \rrbracket}}(\pi_v,\pi_w)
&=\sup_{p\in \mathbf{D}_0}\{d_{\overline{\mathbb{K}}}((\pi_v)_0(p),(\pi_w)_0(p))\}\nonumber\\
&=\sup_{p\in \mathbf{D}_0}\{d_{\overline{\mathbb{K}}}(p(v),p(w))\}\nonumber\\
&=\sup_{p\in \mathbf{D}_0}\{p(w)-p(v)\}.\label{d_dk}
\end{align}
